CREATE TABLE settings_grant_versions (
    host_id TEXT NOT NULL CHECK (length(host_id)=36 AND lower(host_id)=host_id AND host_id NOT GLOB '*[^0-9a-f-]*' AND length(replace(host_id,'-',''))=32 AND substr(host_id,9,1)='-' AND substr(host_id,14,1)='-' AND substr(host_id,19,1)='-' AND substr(host_id,24,1)='-' AND host_id<>'00000000-0000-0000-0000-000000000000'),
    device_id TEXT NOT NULL REFERENCES devices(id) CHECK (length(device_id)=36 AND lower(device_id)=device_id AND device_id NOT GLOB '*[^0-9a-f-]*' AND length(replace(device_id,'-',''))=32 AND substr(device_id,9,1)='-' AND substr(device_id,14,1)='-' AND substr(device_id,19,1)='-' AND substr(device_id,24,1)='-' AND device_id<>'00000000-0000-0000-0000-000000000000' AND device_id<>host_id),
    revision INTEGER NOT NULL CHECK (revision>0),
    grant_id TEXT NOT NULL CHECK (length(grant_id)=36 AND lower(grant_id)=grant_id AND grant_id NOT GLOB '*[^0-9a-f-]*' AND length(replace(grant_id,'-',''))=32 AND substr(grant_id,9,1)='-' AND substr(grant_id,14,1)='-' AND substr(grant_id,19,1)='-' AND substr(grant_id,24,1)='-' AND grant_id<>'00000000-0000-0000-0000-000000000000'),
    owner_request_id TEXT NOT NULL CHECK (length(owner_request_id)=36 AND lower(owner_request_id)=owner_request_id AND owner_request_id NOT GLOB '*[^0-9a-f-]*' AND length(replace(owner_request_id,'-',''))=32 AND substr(owner_request_id,9,1)='-' AND substr(owner_request_id,14,1)='-' AND substr(owner_request_id,19,1)='-' AND substr(owner_request_id,24,1)='-' AND owner_request_id<>'00000000-0000-0000-0000-000000000000'),
    record TEXT NOT NULL CHECK (json_valid(record) AND json_type(record)='object' AND length(CAST(record AS BLOB)) BETWEEN 1 AND 8192),
    receipt TEXT NOT NULL CHECK (json_valid(receipt) AND json_type(receipt)='object' AND length(CAST(receipt AS BLOB)) BETWEEN 1 AND 512),
    PRIMARY KEY (host_id,device_id,revision),
    UNIQUE (host_id,owner_request_id),
    CHECK (coalesce(json_extract(record,'$.version')=1 AND json_extract(record,'$.host_id')=host_id AND json_extract(record,'$.owner_principal_id')=host_id AND json_type(record,'$.revision')='integer' AND json_extract(record,'$.revision')=revision AND json_extract(record,'$.change.version')=1 AND json_extract(record,'$.change.request_id')=owner_request_id AND json_extract(record,'$.change.peer_keys.device_id')=device_id AND json_extract(record,'$.change.target.grant_id')=grant_id,0)),
    CHECK (coalesce(json_type(record,'$.change.target.issued_at')='integer' AND json_extract(record,'$.change.target.issued_at')>0 AND json_type(record,'$.change.target.expires_at')='integer' AND json_extract(record,'$.change.target.expires_at')>json_extract(record,'$.change.target.issued_at') AND json_extract(record,'$.change.target.expires_at')-json_extract(record,'$.change.target.issued_at')<=604800000 AND json_type(record,'$.change.rotate') IN ('true','false') AND json_type(record,'$.change.expected') IN ('null','object') AND json_extract(record,'$.change.target.state.kind') IN ('active','revoked') AND (json_extract(record,'$.change.target.state.kind')<>'active' OR revision<9223372036854775807),0)),
    CHECK (coalesce(json_extract(receipt,'$.version')=1 AND json_extract(receipt,'$.host_id')=host_id AND json_extract(receipt,'$.device_id')=device_id AND json_extract(receipt,'$.owner_request_id')=owner_request_id AND json_extract(receipt,'$.grant_id')=grant_id AND json_extract(receipt,'$.revision')=revision AND json_type(receipt,'$.committed_at')='integer' AND json_extract(receipt,'$.committed_at')>=json_extract(record,'$.change.target.issued_at') AND json_extract(receipt,'$.committed_at')<json_extract(record,'$.change.target.expires_at') AND length(json_extract(receipt,'$.request_sha256'))=64 AND json_extract(receipt,'$.request_sha256') NOT GLOB '*[^0-9a-f]*',0))
) STRICT;
CREATE INDEX settings_grant_family ON settings_grant_versions(host_id,grant_id);
CREATE TABLE settings_grant_heads (
    host_id TEXT NOT NULL,
    device_id TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision>0),
    grant_id TEXT NOT NULL,
    revocation_reserved INTEGER NOT NULL CHECK (revocation_reserved IN (0,1)),
    PRIMARY KEY (host_id,device_id),
    FOREIGN KEY (host_id,device_id,revision) REFERENCES settings_grant_versions(host_id,device_id,revision)
) STRICT;
CREATE TRIGGER settings_grant_versions_insert BEFORE INSERT ON settings_grant_versions BEGIN
    SELECT CASE WHEN EXISTS(SELECT 1 FROM settings_grant_versions v WHERE v.host_id=NEW.host_id AND v.owner_request_id=NEW.owner_request_id) THEN RAISE(ABORT,'Settings grant original owner request is immutable') END;
    SELECT CASE WHEN (SELECT count(*) FROM json_each(NEW.record))<>5 OR (SELECT count(*) FROM json_each(NEW.record,'$.change'))<>7 OR (SELECT count(*) FROM json_each(NEW.record,'$.change.peer_keys'))<>3 OR (SELECT count(*) FROM json_each(NEW.record,'$.change.target'))<>4 OR (SELECT count(*) FROM json_each(NEW.receipt))<>8 THEN RAISE(ABORT,'Settings grant closed record shape') END;
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM transport_endpoint e WHERE e.singleton=1 AND e.device_id=NEW.host_id AND json_extract(e.configuration,'$.version')=1 AND json_extract(e.configuration,'$.keys.device_id')=NEW.host_id AND json_extract(e.configuration,'$.role.role')='host' AND (e.revoked_at IS NULL OR (json_extract(NEW.record,'$.change.target.state.kind')='revoked' AND EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id)))
    ) THEN RAISE(ABORT,'Settings grant Host endpoint mismatch') END;
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM devices d WHERE d.id=NEW.device_id AND json_extract(d.public_identity,'$.version')=1 AND json_extract(d.public_identity,'$.keys.device_id')=NEW.device_id AND json_extract(d.public_identity,'$.keys.signing_key')=json_extract(NEW.record,'$.change.peer_keys.signing_key') AND json_extract(d.public_identity,'$.keys.encryption_key')=json_extract(NEW.record,'$.change.peer_keys.encryption_key') AND (d.revoked_at IS NULL OR (json_extract(NEW.record,'$.change.target.state.kind')='revoked' AND EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id)))
    ) THEN RAISE(ABORT,'Settings grant complete pin mismatch') END;
    SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id) AND (NEW.revision<>1 OR json_type(NEW.record,'$.change.expected')<>'null' OR json_extract(NEW.record,'$.change.rotate')<>0) THEN RAISE(ABORT,'Settings grant creation expectation') END;
    SELECT CASE WHEN EXISTS (
        SELECT 1 FROM settings_grant_heads h JOIN settings_grant_versions v ON v.host_id=h.host_id AND v.device_id=h.device_id AND v.revision=h.revision WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id AND NOT coalesce(h.revision<9223372036854775807 AND NEW.revision=h.revision+1 AND json_type(NEW.record,'$.change.expected')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.change.expected'))=2 AND json_extract(NEW.record,'$.change.expected.grant_id')=h.grant_id AND json_extract(NEW.record,'$.change.expected.revision')=h.revision AND json_extract(NEW.record,'$.change.rotate')=(NEW.grant_id<>h.grant_id) AND json_extract(NEW.record,'$.change.peer_keys.signing_key')=json_extract(v.record,'$.change.peer_keys.signing_key') AND json_extract(NEW.record,'$.change.peer_keys.encryption_key')=json_extract(v.record,'$.change.peer_keys.encryption_key'),0)
    ) THEN RAISE(ABORT,'Settings grant head compare-and-swap conflict') END;
    SELECT CASE WHEN EXISTS(SELECT 1 FROM settings_grant_versions v WHERE v.host_id=NEW.host_id AND v.grant_id=NEW.grant_id) AND NOT EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id AND h.grant_id=NEW.grant_id) THEN RAISE(ABORT,'Settings grant identity is retired') END;
    SELECT CASE WHEN json_extract(NEW.record,'$.change.target.state.kind')='revoked' AND (SELECT count(*) FROM json_each(NEW.record,'$.change.target.state'))<>1 THEN RAISE(ABORT,'Settings revoked grant shape') END;
    SELECT CASE WHEN json_extract(NEW.record,'$.change.target.state.kind')='active' AND NOT coalesce((SELECT count(*) FROM json_each(NEW.record,'$.change.target.state'))=4 AND json_type(NEW.record,'$.change.target.state.readable_keys')='array' AND json_array_length(NEW.record,'$.change.target.state.readable_keys')<=5 AND json_type(NEW.record,'$.change.target.state.writable_keys')='array' AND json_array_length(NEW.record,'$.change.target.state.writable_keys')<=2 AND json_type(NEW.record,'$.change.target.state.session_consent')='object',0) THEN RAISE(ABORT,'Settings active grant shape') END;
    SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.record,'$.change.target.state.readable_keys') k WHERE k.type<>'text' OR k.value NOT IN ('models.selection','tools.selection','memory.embeddings.enabled','memory.embeddings.dimensions','memory.embeddings.model')) OR EXISTS(SELECT 1 FROM json_each(NEW.record,'$.change.target.state.writable_keys') k WHERE k.type<>'text' OR k.value NOT IN ('memory.embeddings.enabled','memory.embeddings.dimensions') OR NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.change.target.state.readable_keys') r WHERE r.value=k.value)) THEN RAISE(ABORT,'Settings grant key scope') END;
    SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.record,'$.change.target.state.readable_keys') a JOIN json_each(NEW.record,'$.change.target.state.readable_keys') b ON a.key<b.key WHERE (CASE a.value WHEN 'models.selection' THEN 1 WHEN 'tools.selection' THEN 2 WHEN 'memory.embeddings.enabled' THEN 3 WHEN 'memory.embeddings.dimensions' THEN 4 WHEN 'memory.embeddings.model' THEN 5 ELSE 0 END)>=(CASE b.value WHEN 'models.selection' THEN 1 WHEN 'tools.selection' THEN 2 WHEN 'memory.embeddings.enabled' THEN 3 WHEN 'memory.embeddings.dimensions' THEN 4 WHEN 'memory.embeddings.model' THEN 5 ELSE 0 END)) OR EXISTS(SELECT 1 FROM json_each(NEW.record,'$.change.target.state.writable_keys') a JOIN json_each(NEW.record,'$.change.target.state.writable_keys') b ON a.key<b.key WHERE (CASE a.value WHEN 'models.selection' THEN 1 WHEN 'tools.selection' THEN 2 WHEN 'memory.embeddings.enabled' THEN 3 WHEN 'memory.embeddings.dimensions' THEN 4 WHEN 'memory.embeddings.model' THEN 5 ELSE 0 END)>=(CASE b.value WHEN 'models.selection' THEN 1 WHEN 'tools.selection' THEN 2 WHEN 'memory.embeddings.enabled' THEN 3 WHEN 'memory.embeddings.dimensions' THEN 4 WHEN 'memory.embeddings.model' THEN 5 ELSE 0 END)) THEN RAISE(ABORT,'Settings grant keys must be sorted and unique') END;
    SELECT CASE WHEN NOT coalesce(((json_extract(NEW.record,'$.change.target.state.kind')='revoked' OR json_extract(NEW.record,'$.change.target.state.session_consent.kind')='none') AND json_type(NEW.record,'$.change.configured_settings_revision')='null') OR (json_extract(NEW.record,'$.change.target.state.kind')='active' AND json_extract(NEW.record,'$.change.target.state.session_consent.kind')='configured_provider' AND json_type(NEW.record,'$.change.configured_settings_revision')='integer' AND json_extract(NEW.record,'$.change.configured_settings_revision')>0),0) THEN RAISE(ABORT,'Settings grant configured revision provenance') END;
    SELECT CASE WHEN json_extract(NEW.record,'$.change.target.state.kind')='active' AND NOT coalesce((json_extract(NEW.record,'$.change.target.state.session_consent.kind')='none' AND (SELECT count(*) FROM json_each(NEW.record,'$.change.target.state.session_consent'))=1) OR (json_extract(NEW.record,'$.change.target.state.session_consent.kind')='configured_provider' AND (SELECT count(*) FROM json_each(NEW.record,'$.change.target.state.session_consent'))=4 AND json_extract(NEW.record,'$.change.target.state.session_consent.provider') IN ('openai','anthropic') AND json_type(NEW.record,'$.change.target.state.session_consent.model')='text' AND length(CAST(json_extract(NEW.record,'$.change.target.state.session_consent.model') AS BLOB)) BETWEEN 1 AND 256 AND json_type(NEW.record,'$.change.target.state.session_consent.recipient')='text' AND length(CAST(json_extract(NEW.record,'$.change.target.state.session_consent.recipient') AS BLOB)) BETWEEN 1 AND 4096),0) THEN RAISE(ABORT,'Settings grant consent shape') END;
    SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id) AND (SELECT count(*) FROM settings_grant_heads)>=4096 THEN RAISE(ABORT,'Settings grant head capacity') END;
    SELECT CASE WHEN (SELECT count(*) FROM settings_grant_versions)+1+((SELECT coalesce(sum(revocation_reserved),0) FROM settings_grant_heads)+(json_extract(NEW.record,'$.change.target.state.kind')='active')-coalesce((SELECT revocation_reserved FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id),0))>8192 THEN RAISE(ABORT,'Settings grant version and receipt reserve capacity') END;
    SELECT CASE WHEN (SELECT coalesce(sum(length(CAST(record AS BLOB))),0) FROM settings_grant_versions)+length(CAST(NEW.record AS BLOB))+2048*((SELECT coalesce(sum(revocation_reserved),0) FROM settings_grant_heads)+(json_extract(NEW.record,'$.change.target.state.kind')='active')-coalesce((SELECT revocation_reserved FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id),0))>33554432 THEN RAISE(ABORT,'Settings grant version byte reserve capacity') END;
    SELECT CASE WHEN (SELECT coalesce(sum(length(CAST(receipt AS BLOB))),0) FROM settings_grant_versions)+length(CAST(NEW.receipt AS BLOB))+512*((SELECT coalesce(sum(revocation_reserved),0) FROM settings_grant_heads)+(json_extract(NEW.record,'$.change.target.state.kind')='active')-coalesce((SELECT revocation_reserved FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id),0))>4194304 THEN RAISE(ABORT,'Settings grant receipt byte reserve capacity') END;
    SELECT CASE WHEN json_extract(NEW.record,'$.change.target.state.kind')='revoked' AND EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id AND h.revocation_reserved=1) AND length(CAST(NEW.record AS BLOB))>2048 THEN RAISE(ABORT,'Settings grant revoke exceeds reserved bytes') END;
END;
CREATE TRIGGER settings_grant_versions_install AFTER INSERT ON settings_grant_versions BEGIN
    INSERT INTO settings_grant_heads(host_id,device_id,revision,grant_id,revocation_reserved) VALUES(NEW.host_id,NEW.device_id,NEW.revision,NEW.grant_id,json_extract(NEW.record,'$.change.target.state.kind')='active') ON CONFLICT(host_id,device_id) DO UPDATE SET revision=excluded.revision,grant_id=excluded.grant_id,revocation_reserved=excluded.revocation_reserved;
END;
CREATE TRIGGER settings_grant_heads_insert BEFORE INSERT ON settings_grant_heads BEGIN
    SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM settings_grant_versions v WHERE v.host_id=NEW.host_id AND v.device_id=NEW.device_id AND v.revision=NEW.revision AND v.grant_id=NEW.grant_id AND NEW.revocation_reserved=(json_extract(v.record,'$.change.target.state.kind')='active') AND ((NEW.revision=1 AND NOT EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id)) OR EXISTS(SELECT 1 FROM settings_grant_heads h WHERE h.host_id=NEW.host_id AND h.device_id=NEW.device_id AND h.revision<9223372036854775807 AND NEW.revision=h.revision+1))) THEN RAISE(ABORT,'Settings grant head must install exact next version') END;
END;
CREATE TRIGGER settings_grant_heads_update BEFORE UPDATE ON settings_grant_heads BEGIN
    SELECT CASE WHEN NEW.host_id<>OLD.host_id OR NEW.device_id<>OLD.device_id OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM settings_grant_versions v WHERE v.host_id=NEW.host_id AND v.device_id=NEW.device_id AND v.revision=NEW.revision AND v.grant_id=NEW.grant_id AND NEW.revocation_reserved=(json_extract(v.record,'$.change.target.state.kind')='active')) THEN RAISE(ABORT,'Settings grant head identity or reserve is immutable outside next version') END;
END;
CREATE TRIGGER settings_grant_versions_no_update BEFORE UPDATE ON settings_grant_versions BEGIN SELECT RAISE(ABORT,'Settings grant version and receipt are immutable'); END;
CREATE TRIGGER settings_grant_versions_no_delete BEFORE DELETE ON settings_grant_versions BEGIN SELECT RAISE(ABORT,'Settings grant version and receipt are immutable'); END;
CREATE TRIGGER settings_grant_heads_no_delete BEFORE DELETE ON settings_grant_heads BEGIN SELECT RAISE(ABORT,'Settings grant head is retained'); END;
